// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant DEPLOYER = address(0xb0b);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint96 amount, address actor) public {
        // Bound to avoid overflow (balance is uint)
        amount = uint96(bound(amount, 1, type(uint96).max));
        vm.assume(actor != address(this) && actor != address(c) && actor != DEPLOYER);

        // Deploy a helper contract that will revert on receiving ETH
        // This is the adversarial counterparty needed because the bug is about failed calls
        // and the fuzzer cannot synthesize a failing contract from a raw address parameter.
        Reverter reverter = new Reverter();

        // 1. Deposit to actor and to the reverter so they both have credit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.deal(address(reverter), amount);
        vm.prank(address(reverter));
        c.deposit{value: amount}();

        // Record state before withdrawals
        uint256 balanceBefore = address(c).balance;

        // 2. Actor withdraws successfully (actor is EOA, call succeeds)
        vm.prank(actor);
        c.withdrawAll();

        // 3. Reverter withdraws; its receive() reverts so the ETH transfer fails
        //    In the reference contract, the whole withdrawAll reverts.
        //    In the buggy version, it succeeds but deducts balance and credit without sending ETH.
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Assertion: In the reference contract, either the withdrawal succeeded (ok == true) and the contract's
        // ETH balance decreased by the reverter's credit (amount), OR it reverted (ok == false) and balance remained unchanged.
        // In both correct cases: address(c).balance == balanceBefore - amount if ok, else balanceBefore.
        // The buggy version violates this: it does not revert (ok == true) but also does not send ETH,
        // so address(c).balance == balanceBefore, which does not match balanceBefore - amount.
        uint256 expected = ok ? balanceBefore - amount : balanceBefore;
        assertTrue(address(c).balance == expected);
    }
}

contract Reverter {
    receive() external payable {
        revert("ETH transfer failed");
    }
}

