pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Keep amounts within a reasonable range
        uint128 maxAmt = type(uint128).max;
        vm.assume(depositAmount > 0 && depositAmount <= maxAmt);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= maxAmt);
        // Deploy an adversarial callee that rejects ETH
        Reverter reverter = new Reverter();
        address adversary = address(reverter);
        // Give adversary some deposit
        vm.deal(adversary, depositAmount);
        vm.prank(adversary);
        c.deposit{value: depositAmount}();
        // The adversary has depositAmount credit
        // Now adversary calls withdrawAll, which will attempt ETH transfer to itself
        // Capture result: reference should revert, buggy does not
        bool ok;
        vm.prank(adversary);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // After the call, if it didn't revert (buggy), balance will be decremented
        // but ETH remains in c (adversary rejected). Thus balance != address(c).balance.
        // If it reverted (reference), balance == address(c).balance holds.
        uint256 cBalance = c.balance();
        uint256 cEth = address(c).balance;
        // The property: if the call succeeded (ok == true), then cBalance must equal cEth.
        // Reference: ok is always false, so property vacuously true.
        // Buggy: ok can be true, but cBalance != cEth, violating property.
        assertTrue(!ok || cBalance == cEth);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

