pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address depositor, address withdrawer) public {
        // Admissible domain: positive amounts and distinct actors to avoid collision complexity
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount < type(uint128).max);
        vm.assume(depositor != withdrawer && depositor != address(this) && withdrawer != address(this));
        vm.assume(depositor != address(0) && withdrawer != address(0));

        // Depositor makes a deposit
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // Withdrawer deposits a different amount to establish credit
        vm.deal(withdrawer, withdrawAmount);
        vm.prank(withdrawer);
        c.deposit{value: withdrawAmount}();

        // Calculate total deposited Ether
        uint256 totalDeposited = depositAmount + withdrawAmount;

        // Withdrawer withdraws all its credit
        vm.prank(withdrawer);
        c.withdrawAll();

        // After withdrawal, sum of all credits (only depositor's remains) plus balance must equal total deposited
        // We cannot iterate the mapping, but we know depositor's credit is untouched and withdrawer's is zero
        uint256 depositorCredit = c.credit(depositor);
        uint256 withdrawerCredit = c.credit(withdrawer);
        uint256 contractBalance = address(c).balance;
        uint256 balanceVar = c.balance();

        // The invariant: contract ETH balance equals balance variable (always true in correct C)
        // and sum of known credits plus balance equals total deposited
        assertTrue(contractBalance == balanceVar && depositorCredit + withdrawerCredit + contractBalance == totalDeposited);
    }
}

