pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmt, uint256 withdrawAmtAfter) public {
        // bound amounts and avoid zero address
        vm.assume(actor != address(0));
        depositAmt = bound(depositAmt, 1, 1000 ether);
        withdrawAmtAfter = bound(withdrawAmtAfter, 1, 1000 ether);

        // actor deposits
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        // deploy a reverter to make the external call fail on the subsequent withdraw
        Reverter r = new Reverter();

        // another deposit from the reverter creates credit for r
        vm.deal(address(r), withdrawAmtAfter);
        vm.prank(address(r));
        c.deposit{value: withdrawAmtAfter}();

        // now the reverter tries to withdraw — the fallback reverts, so the call fails
        vm.prank(address(r));
        try c.withdrawAll() { } catch { }

        // GENERAL RULE: contract's ether balance must equal sum of credits of all participants
        // The correct contract still satisfies this after the failed withdrawal.
        // The buggy one resets credit before the external call, leaving credit > 0 while balance was reduced,
        // so balance becomes smaller than sum of credits.
        uint256 actorCredit = c.credit(actor);
        uint256 reverterCredit = c.credit(address(r));
        uint256 totalCredit = actorCredit + reverterCredit;
        uint256 ethBal = address(c).balance;
        assertTrue(ethBal == totalCredit);
    }
