pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user) public {
        vm.assume(user != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= 1000 ether);

        // Deploy adversarial reverter helper that reverts on receiving ETH
        Reverter r = new Reverter();

        // User deposits some ETH
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Now the reverter deposits as well, so it has credit and can trigger withdrawAll
        uint revertDeposit = withdrawAmount;
        vm.assume(revertDeposit <= depositAmount); // Avoid overflow, keep reasonable
        vm.deal(address(r), revertDeposit);
        vm.prank(address(r));
        c.deposit{value: revertDeposit}();

        // Reverter calls withdrawAll, which will fail on ETH transfer, but bug resets credit after?
        // Actually bug: balance -= oCredit; then external call; require(callResult); credit[r] = 0;
        // So if call reverts, require fails, but balance already reduced and credit NOT reset (in buggy version).
        // We need reverter to NOT have credit zeroed so it can try again and drain more.
        // But the assert we want: after call (which may revert), contract balance >= sum credits.
        // We'll just call withdrawAll from reverter; it will revert because fallback reverts.
        // We check that after revert, balance >= credit[reverter] (caller's credit)
        vm.prank(address(r));
        try c.withdrawAll() {} catch {}

        // After the call, the invariant: contract balance >= sum of all credits
        uint totalCredits = c.credit(user) + c.credit(address(r));
        assertTrue(address(c).balance >= totalCredits);
    }
}

